inline String findGlobalCityName(const String& rawCode) {
  if (rawCode.length() == 0) return "";
  String code = rawCode;
  code.trim();
  code.toUpperCase();

  int low = 0;
  int high = NUM_GLOBAL_AIRPORTS - 1;

  while (low <= high) {
    int mid = (low + high) / 2;
    char entryCode[5];
    memcpy_P(entryCode, &GLOBAL_AIRPORTS[mid].code, sizeof(entryCode));

    int cmp = strcmp(code.c_str(), entryCode);
    if (cmp == 0) {
      char entryCity[24];
      memcpy_P(entryCity, &GLOBAL_AIRPORTS[mid].city, sizeof(entryCity));
      return String(entryCity);
    } else if (cmp < 0) {
      high = mid - 1;
    } else {
      low = mid + 1;
    }
  }

  if (code.length() == 4) {
    String iata = code.substring(1);
    low = 0;
    high = NUM_GLOBAL_AIRPORTS - 1;
    while (low <= high) {
      int mid = (low + high) / 2;
      char entryCode[5];
      memcpy_P(entryCode, &GLOBAL_AIRPORTS[mid].code, sizeof(entryCode));

      int cmp = strcmp(iata.c_str(), entryCode);
      if (cmp == 0) {
        char entryCity[24];
        memcpy_P(entryCity, &GLOBAL_AIRPORTS[mid].city, sizeof(entryCity));
        return String(entryCity);
      } else if (cmp < 0) {
        high = mid - 1;
      } else {
        low = mid + 1;
      }
    }
  }

  return "";
}
